-- 0266: converge any journal-less (push-era) schema to current.
--
-- Prod's schema was created without drizzle's journal table, so the deploy's
-- first `pnpm db:migrate` replayed from 0000 and crashed on an existing
-- relation. The deploy now baselines the journal (pre-migrate guard) and this
-- migration converges the underlying schema to current WITHOUT assuming which
-- effects the historical push already applied. Every statement is therefore:
--   - guarded (IF NOT EXISTS / catalog-check DO blocks), safe to run twice
--   - additive or a structure-only repair; NOTHING is dropped
--   - copied from the published chain (journal order) with the same
--     internal ordering, so backfill-before-NOT-NULL sequences survive
-- Data repairs run once by predicate: re-runs match no rows.
--> statement-breakpoint

-- ==== 0000_extensions ====
--> statement-breakpoint

-- Extensions first: the generated migration that follows uses `vector` for
-- embeddings and will use `pg_trgm`/full-text once search lands. Generated by
-- `drizzle-kit generate --custom`, kept ahead of the schema migration because
-- drizzle-kit does not emit CREATE EXTENSION itself.
--
-- One statement per batch: drizzle's migrator splits on the breakpoint marker,
-- so without them the driver is handed four statements as one string, which the
-- Neon HTTP path rejects. 0001 depends on `vector` already existing.
--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS vector;
--> statement-breakpoint

CREATE EXTENSION IF NOT EXISTS pg_trgm;
--> statement-breakpoint

CREATE EXTENSION IF NOT EXISTS citext;
--> statement-breakpoint

CREATE EXTENSION IF NOT EXISTS pgcrypto;
--> statement-breakpoint

-- ==== 0001_greedy_whistler ====
--> statement-breakpoint

