-- ==== 0262_one_running_creation_run ====
--> statement-breakpoint

-- Review should-fix F: two concurrent create-stream POSTs could both pass the
-- "existing running run" pre-check and start two runs for one sitting. The
-- pre-check stays as the fast path; this partial unique index is the actual
-- guard: at most one RUNNING creation run per (workspace, sitting).
--> statement-breakpoint

-- Convergence repair: 0262's unique index presumes no duplicate RUNNING
-- zettel-sitting-creation runs per (workspace, sitting) -- the exact race the
-- index was added to close. Keep the earliest run per sitting and cancel the
-- superseded zombies. Rows whose sitting key is null never conflict in the
-- index (NULLS DISTINCT) and are left alone. Re-runs match no rows.
WITH ranked AS (
  SELECT id, row_number() OVER (
    PARTITION BY workspace_id, (subjects->0->>'sittingId')
    ORDER BY started_at ASC, id ASC
  ) AS rn
  FROM "agent_runs"
  WHERE "objective" = 'zettel-sitting-creation'
    AND "state" = 'running'
    AND (subjects->0->>'sittingId') IS NOT NULL
)
UPDATE "agent_runs" r
SET state = 'cancelled', ended_at = now(), updated_at = now()
FROM ranked x
WHERE r.id = x.id AND x.rn > 1;
--> statement-breakpoint

CREATE UNIQUE INDEX IF NOT EXISTS "agent_runs_one_running_creation_per_sitting"
ON "agent_runs" ("workspace_id", ((subjects->0->>'sittingId')))
WHERE "objective" = 'zettel-sitting-creation' AND "state" = 'running';
--> statement-breakpoint

